#pragma warning disable 8981

using System.Collections.Generic;
using System.IO;

namespace Ros.Config
{
    public partial class ConfigManager
    {
        public Dictionary<pageEnum, page> pageData;
        public page GetpageConfig(pageEnum key)
        {
            return ConfigBinary.Require(pageData, key, "page");
        }
        private void LoadpageConfig()
        {
            using (BinaryReader r = ConfigBinary.Open("page"))
            {
                int count = r.ReadInt32();
                pageData = new Dictionary<pageEnum, page>(count);
                for (int i = 0; i < count; i++)
                {
                    page row;
                    row.key = (pageEnum)r.ReadInt32();
                    row.order = r.ReadInt32();
                    row.blackMask = r.ReadByte() != 0;
                    row.closeOnOutsideClick = r.ReadByte() != 0;
                    pageData.Add(row.key, row);
                }
            }
        }
    }
    public struct page
    {
        public pageEnum key;  // 主键
        public int order;  // 层级：显示层级，越大越靠上；同层级互斥
        public bool blackMask;  // 显示黑屏遮罩：是否显示黑屏遮罩
        public bool closeOnOutsideClick;  // 点击外部关闭：点击面板外部是否收起本界面
    }
    public enum pageEnum
    {
        home,
        lobby,
        battle,
        chat,
        robot_tv,
        gm,
        settings,
        rule,
        guide,
        confirm,
        loading,
    }
}
